import {configureToolInputs,markResultStale} from './form-behavior.mjs';
import {escapeHTML as e,formatNumber as n} from './core.mjs';
import {icon} from './catalog.mjs';
export {e,n};
export const number=(id,label,value,min,max,step='any')=>({id,label,type:'number',value,min,max,step});
export const select=(id,label,options,value)=>({id,label,type:'select',options,value});
export const text=(id,label,value='',type='text',full=false)=>({id,label,type,value,full});
export const area=(id,label,value='',placeholder='')=>({id,label,type:'textarea',value,placeholder,full:true});
export function field(f){let attrs=`id="f-${e(f.id)}" name="${e(f.id)}" autocomplete="off" autocapitalize="off" autocorrect="off" spellcheck="false" ${f.required===false?'':'required'} ${f.min!==undefined?`min="${e(f.min)}"`:''} ${f.max!==undefined?`max="${e(f.max)}"`:''} ${f.step?`step="${e(f.step)}"`:''}`;let body=f.type==='select'?`<select ${attrs}>${f.options.map(o=>{let [v,l]=Array.isArray(o)?o:[o,o];return`<option value="${e(v)}" ${String(f.value)===String(v)?'selected':''}>${e(l)}</option>`;}).join('')}</select>`:f.type==='textarea'?`<textarea ${attrs} placeholder="${e(f.placeholder||'')}">${e(f.value)}</textarea>`:`<input ${attrs} type="${e(f.type||'text')}" value="${e(f.value??'')}" ${f.placeholder?`placeholder="${e(f.placeholder)}"`:''}>`;return`<label class="field ${f.full?'full':''}"><span>${e(f.label)}</span>${body}${f.hint?`<small>${e(f.hint)}</small>`:''}</label>`;}
const outputResources=new WeakMap();
export function registerResource(el,release){if(!outputResources.has(el))outputResources.set(el,new Set());outputResources.get(el).add(release);return release;}
export function clearOutput(el){if(!el)return;const resources=outputResources.get(el);if(resources){for(const release of [...resources])release();outputResources.delete(el);}}
export function result(el,{label='Your result',value,details=[],html='',copy,note=''}){clearOutput(el);el.removeAttribute('data-result-stale');el.innerHTML=`<div class="panel-top"><h2>All done. Here’s your result.</h2><span class="status-pill">${icon('check')} Ready</span></div>${value!==undefined?`<div class="result-label">${e(label)}</div><div class="result-value">${e(value)}</div>`:''}${html}${details.length?`<dl class="result-details">${details.map(([a,b])=>`<div><dt>${e(a)}</dt><dd>${e(b)}</dd></div>`).join('')}</dl>`:''}${note?`<p class="form-note">${e(note)}</p>`:''}${copy!==undefined?`<div class="result-actions"><button class="btn secondary small" data-copy>${icon('copy')} Copy result</button></div>`:''}`;if(copy!==undefined)el.querySelector('[data-copy]').onclick=()=>copyText(String(copy));}
export async function copyText(str){try{await navigator.clipboard.writeText(str);notify('Copied to clipboard');}catch{notify('Clipboard unavailable. Select and copy the result.');}}
let toastTimer;export function notify(message){const t=document.querySelector('#toast');t.textContent=message;t.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('visible'),3200);}
export function error(el,message){el.innerHTML=`<div class="error-box" role="alert">${e(message)}</div>`;}
export function outputText(el,value,details=[]){result(el,{html:`<pre class="result-output">${e(value)}</pre>`,copy:value,details});}
export function form(mount,fields,run,{label='Calculate',note='',auto=true}={}){mount.innerHTML=`<h2>Make it your own</h2><form autocomplete="off"><div class="form-grid">${fields.map(field).join('')}</div><div class="form-actions"><button class="btn primary" type="submit">${e(label)} ${icon('arrow')}</button><button class="btn secondary" type="reset">Reset</button></div>${note?`<p class="form-note">${note}</p>`:''}<div class="form-error"></div></form>`;configureToolInputs(mount);const f=mount.querySelector('form');const execute=async(ev)=>{ev?.preventDefault();if(!f.reportValidity())return;const vals=Object.fromEntries(new FormData(f)),revision=mount.dataset.inputRevision;const b=f.querySelector('[type=submit]');b.disabled=true;f.querySelector('.form-error').innerHTML='';try{await run(vals,f);if(mount.dataset.inputRevision!==revision)markResultStale(document.querySelector('#tool-result'));}catch(err){error(f.querySelector('.form-error'),err.message||'Something went wrong. Please try again.');}finally{b.disabled=false;}};f.addEventListener('submit',execute);f.addEventListener('reset',()=>setTimeout(()=>{f.querySelector('.form-error').innerHTML='';if(auto)execute();},0));if(auto)execute();return f;}
export function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.rel='noopener';a.style.display='none';document.body.append(a);a.click();a.remove();showImageDownload(blob,name);setTimeout(()=>URL.revokeObjectURL(url),60000);}
export function linkDownload(control,blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a'),out=control.closest('#tool-result');a.className=control.className;a.innerHTML=control.innerHTML;a.href=url;a.download=name;a.rel='noopener';a.dataset.download='';a.addEventListener('click',()=>showImageDownload(blob,name));control.replaceWith(a);let released=false;const release=()=>{if(released)return;released=true;URL.revokeObjectURL(url);outputResources.get(out)?.delete(release);};if(out)registerResource(out,release);return release;}
let downloadDialog,downloadPreview,downloadFocus;
function showImageDownload(blob,name){
 if(!blob.type.startsWith('image/'))return;
 if(!downloadDialog){
  downloadDialog=document.createElement('dialog');downloadDialog.className='download-dialog';downloadDialog.setAttribute('aria-labelledby','download-dialog-title');downloadDialog.setAttribute('aria-describedby','download-dialog-note');
  downloadDialog.innerHTML=`<button type="button" class="download-close icon-btn" aria-label="Close download popup">×</button><div class="download-celebration" aria-hidden="true"><i></i><i></i><i></i><i></i><span>${icon('check')}</span></div><p class="download-eyebrow">A LITTLE TASK, TAKEN CARE OF</p><h2 id="download-dialog-title">Your image is on its way.</h2><p id="download-dialog-note">Your download has started. If your browser asks, choose where to save it.</p><div class="download-file"><div class="download-thumb"><img alt="Downloaded image preview"></div><div><strong data-download-name></strong><small data-download-size></small></div><span class="status-pill">${icon('check')} Ready</span></div><div class="download-dialog-actions"><button type="button" class="btn primary" data-keep-editing autofocus>Keep editing ${icon('arrow')}</button><button type="button" class="btn secondary" data-next-image>${icon('refresh')} Change image</button></div><p class="download-private">${icon('shield')} Made here. Saved by your browser. Always yours.</p>`;
  document.body.append(downloadDialog);
  downloadDialog.querySelector('.download-close').onclick=downloadDialog.querySelector('[data-keep-editing]').onclick=()=>downloadDialog.close();
  downloadDialog.querySelector('[data-next-image]').onclick=()=>{const change=document.querySelector('#tool-input [data-upload-change]');downloadDialog.close();change?.scrollIntoView({block:'center',behavior:document.body.classList.contains('motion-paused')?'auto':'smooth'});change?.click();};
  downloadDialog.addEventListener('click',ev=>{if(ev.target!==downloadDialog)return;const r=downloadDialog.getBoundingClientRect();if(ev.clientX<r.left||ev.clientX>r.right||ev.clientY<r.top||ev.clientY>r.bottom)downloadDialog.close();});
  downloadDialog.addEventListener('close',()=>{if(downloadPreview)URL.revokeObjectURL(downloadPreview);downloadPreview=null;downloadDialog.querySelector('img').removeAttribute('src');if(downloadFocus?.isConnected)downloadFocus.focus({preventScroll:true});});
 }
 if(downloadPreview)URL.revokeObjectURL(downloadPreview);downloadPreview=URL.createObjectURL(blob);downloadDialog.querySelector('img').src=downloadPreview;downloadDialog.querySelector('[data-download-name]').textContent=name;downloadDialog.querySelector('[data-download-size]').textContent=blob.type.replace('image/','').toUpperCase()+' · '+bytes(blob.size);const change=document.querySelector('#tool-input [data-upload-change]');const next=downloadDialog.querySelector('[data-next-image]');next.hidden=!change;next.innerHTML=icon('refresh')+' '+(change?.textContent.trim()||'Change image');downloadFocus=document.activeElement;if(!downloadDialog.open)downloadDialog.showModal();
}
export const bytes=b=>b<1024?`${b} B`:b<1048576?`${(b/1024).toFixed(1)} KB`:`${(b/1048576).toFixed(2)} MB`;
